<script lang="ts">
 import {onMount} from 'svelte';import {beforeNavigate} from '$app/navigation';
 import {Button} from '$lib/components/ui/button';import {Input} from '$lib/components/ui/input';import {request} from '../api';
 let preferences=$state<any>(null),saved=$state(''),busy=$state(false),error=$state(''),notice=$state('');
 const dirty=$derived(!!preferences&&JSON.stringify(preferences)!==saved);
 beforeNavigate(({cancel})=>{if(dirty&&!window.confirm('Leave without saving playback preferences?'))cancel();});
 onMount(()=>{void request('/settings/preferences').then(v=>{preferences=v;saved=JSON.stringify(v);}).catch(e=>error=e.message);});
 async function save(){busy=true;error='';notice='';try{const {schema_version,...patch}=preferences;preferences=await request('/settings/preferences',patch,'PATCH');saved=JSON.stringify(preferences);notice='Playback preferences saved.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 const rows=[{key:'captions_enabled',title:'Show captions',help:'Use captions when a video includes them.'},{key:'autoplay_next',title:'Autoplay next video',help:'Continue to a related video when the current one ends.'},{key:'shorts_autoplay',title:'Autoplay Shorts',help:'Play the active Short muted when your browser allows it.'},{key:'data_saving',title:'Use less data',help:'Reduce preloading and favour a lower streaming quality when available.'}];
</script>
<div class="page-heading"><h1>Playback</h1><p>Make watching comfortable for you.</p></div>{#if error}<p class="cloud-alert" role="alert">{error}</p>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
{#if preferences}<form onsubmit={e=>{e.preventDefault();void save();}}>{#each rows as row}<label class="preference-row"><span><strong>{row.title}</strong><small>{row.help}</small></span><input type="checkbox" role="switch" bind:checked={preferences[row.key]} disabled={busy}/></label>{/each}<div class="preference-field"><label for="caption-language">Preferred caption language</label><Input id="caption-language" bind:value={preferences.caption_language} maxlength={35} placeholder="For example, en or ms"/><p class="field-help">Leave blank to use the video's available language.</p></div><div class="preference-field"><label for="reduce-motion">Motion</label><select id="reduce-motion" bind:value={preferences.reduce_motion}><option value="system">Follow device preference</option><option value="reduce">Reduce motion</option><option value="no-preference">Standard motion</option></select></div><Button type="submit" disabled={busy||!dirty}>{busy?'Saving…':'Save preferences'}</Button></form>{:else if !error}<p role="status" class="subtle">Loading playback preferences…</p>{/if}
<style>.preference-row{display:flex;align-items:center;gap:24px;justify-content:space-between;padding:20px 0;margin:0;min-height:76px;border-top:1px solid var(--border);cursor:pointer}.preference-row strong{display:block;font-size:14px;font-weight:550}.preference-row small{display:block;color:var(--muted-foreground);font-size:12px;line-height:1.7;margin-top:6px;max-width:55ch}.preference-row input{appearance:none;width:36px;height:21px;flex-shrink:0;background:var(--muted);border:1px solid var(--border);border-radius:20px;position:relative;cursor:pointer}.preference-row input::after{content:"";position:absolute;width:15px;height:15px;border-radius:50%;background:var(--muted-foreground);left:2px;top:2px;transition:transform .15s ease-out}.preference-row input:checked{background:var(--primary)}.preference-row input:checked::after{transform:translateX(15px);background:var(--primary-foreground)}.preference-row input:focus-visible{outline:2px solid var(--ring);outline-offset:4px}@media(prefers-reduced-motion:reduce){.preference-row input::after{transition:none}}.preference-field{padding:22px 0;border-top:1px solid var(--border);display:grid;gap:10px}.preference-field label{font-size:13px}.preference-field select{background:var(--background);color:var(--foreground);border:1px solid var(--border);padding:10px;border-radius:8px;font-size:13px;min-height:40px}form>:global(button){margin-top:8px;min-height:40px}</style>
